-- Align workspace dates, preserve captured sales, exclude test refunds and guard unknown costs.
create or replace function private.shopify_shipping(owner uuid,store uuid,remote_order text,event_date date) returns numeric language sql stable security definer set search_path='' as $$
 select f.shipping_cost_net_amount*private.amazon_rate_to_eur(coalesce(nullif(f.shipping_cost_currency,''),'EUR'),coalesce((f.shipping_cost_recorded_at at time zone private.amazon_analytics_timezone())::date,event_date))
 from public.fulfillment_orders f where f.owner_id=owner and owner=private.shopify_analytics_owner() and f.source_channel='shopify'
 and f.source_integration_account_id=store and (f.order_id=remote_order or f.sendcloud_id='shopify:'||store::text||':'||remote_order)
 order by f.shipping_cost_recorded_at desc nulls last,f.last_synced_at desc nulls last limit 1;$$;

create or replace function public.shopify_analytics_summary(from_date date,to_date date,integration_account_ids uuid[] default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v uuid:=private.shopify_analytics_owner(); result jsonb;begin
 if from_date is null or to_date is null or from_date>to_date then raise exception 'El período no es válido.';end if;
 with eligible as(select o.*,(o.event_at at time zone private.amazon_analytics_timezone())::date d,private.amazon_rate_to_eur(o.currency,(o.event_at at time zone private.amazon_analytics_timezone())::date) fx
 from public.shopify_analytics_orders o join public.integration_accounts a on a.id=o.integration_account_id and a.owner_id=v and a.enabled and a.status<>'disabled'
 where o.owner_id=v and not o.test and o.financial_status in ('PAID','PARTIALLY_PAID','PARTIALLY_REFUNDED','REFUNDED')
 and o.event_at>=(from_date::timestamp at time zone private.amazon_analytics_timezone()) and o.event_at<((to_date+1)::timestamp at time zone private.amazon_analytics_timezone()) and (coalesce(cardinality(integration_account_ids),0)=0 or o.integration_account_id=any(integration_account_ids))),
 sales as(select count(*) orders,coalesce(sum(gross_sales*fx),0) gross,coalesce(sum(sales_vat*fx),0) vat,coalesce(sum(discounts*fx),0) discounts,coalesce(sum(shipping_charged*fx),0) shipping_charged,count(*) filter(where fx is null) missing_fx from eligible),
 cost_rows as(select i.quantity,c.cost,c.missing,c.mapping_count from eligible o join public.shopify_analytics_items i on i.integration_account_id=o.integration_account_id and i.order_id=o.order_id and i.owner_id=v left join lateral private.shopify_cost(v,i.integration_account_id,i.seller_sku,o.d) c on true),
 costs as(select coalesce(sum(quantity),0) units,coalesce(sum(quantity*cost),0) product_cost,count(*) filter(where mapping_count=0) unmapped,count(*) filter(where mapping_count=0 or missing>0) missing from cost_rows),
 shipping_rows as(select case when not requires_shipping then 0 else private.shopify_shipping(v,integration_account_id,order_id,d) end cost from eligible),
 shipping as(select coalesce(sum(cost),0) cost,count(*) filter(where cost is null) missing from shipping_rows),
 refund_rows as(select r.*,private.amazon_rate_to_eur(r.currency,(r.event_at at time zone private.amazon_analytics_timezone())::date) fx from public.shopify_analytics_refunds r join public.integration_accounts a on a.id=r.integration_account_id and a.owner_id=v and a.enabled and a.status<>'disabled'
 where r.owner_id=v and exists(select 1 from public.shopify_analytics_orders ro where ro.integration_account_id=r.integration_account_id and ro.order_id=r.order_id and ro.owner_id=v and not ro.test) and r.event_at>=(from_date::timestamp at time zone private.amazon_analytics_timezone()) and r.event_at<((to_date+1)::timestamp at time zone private.amazon_analytics_timezone()) and (coalesce(cardinality(integration_account_ids),0)=0 or r.integration_account_id=any(integration_account_ids))),
 refunds as(select count(*) n,coalesce(sum(gross_amount*fx),0) gross,coalesce(sum(net_amount*fx),0) net,count(*) filter(where fx is null) missing_fx from refund_rows)
 select jsonb_build_object('grossSales',round(s.gross,2),'salesVat',round(s.vat,2),'netSales',round(s.gross-s.vat,2),'orders',s.orders,'units',c.units,'refunds',round(r.net,2),'refundGross',round(r.gross,2),'refundCount',r.n,'discounts',round(s.discounts,2),'shippingCharged',round(s.shipping_charged,2),'productCost',case when c.missing=0 then round(c.product_cost,2) end,'shippingCost',case when sh.missing=0 then round(sh.cost,2) end,'paymentFees',null,'adsCost',null,'netProfit',null,'profitBeforeAds',case when c.missing+sh.missing+s.missing_fx+r.missing_fx=0 then round(s.gross-s.vat-r.net-c.product_cost-sh.cost,2) end,'marginPct',null,'unmappedSkuCount',c.unmapped,'missingCostCount',c.missing+sh.missing,'missingFxCount',s.missing_fx+r.missing_fx,'profitComplete',false,'currency','EUR','availableFrom',(select min(st.available_from) from public.shopify_analytics_sync_state st where st.owner_id=v and (coalesce(cardinality(integration_account_ids),0)=0 or st.integration_account_id=any(integration_account_ids)))) into result from sales s cross join costs c cross join shipping sh cross join refunds r;
 return result;end;$$;

drop function public.shopify_analytics_products(date,date,uuid[],text,integer,integer);
create or replace function public.shopify_analytics_products(from_date date,to_date date,integration_account_ids uuid[] default null,search text default null,page integer default 1,page_size integer default 50,sort_by text default 'product_name',sort_dir text default 'asc') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v uuid:=private.shopify_analytics_owner(); result jsonb;v_sort text:=coalesce(sort_by,'product_name');v_dir text:=case when lower(sort_dir)='desc' then 'desc' else 'asc' end;v_page integer:=greatest(1,coalesce(page,1));v_size integer:=greatest(1,least(200,coalesce(page_size,50)));begin
 if from_date is null or to_date is null or from_date>to_date then raise exception 'El período no es válido.';end if;
 with stores as(select a.id,a.display_name from public.integration_accounts a where a.owner_id=v and a.provider='shopify' and a.enabled and a.status<>'disabled' and a.credential_source<>'derived' and (coalesce(cardinality(integration_account_ids),0)=0 or a.id=any(integration_account_ids))),
 eligible as(select o.*,(o.event_at at time zone private.amazon_analytics_timezone())::date d,private.amazon_rate_to_eur(o.currency,(o.event_at at time zone private.amazon_analytics_timezone())::date) fx from public.shopify_analytics_orders o join stores s on s.id=o.integration_account_id
 where o.owner_id=v and not o.test and o.financial_status in ('PAID','PARTIALLY_PAID','PARTIALLY_REFUNDED','REFUNDED') and o.event_at>=(from_date::timestamp at time zone private.amazon_analytics_timezone()) and o.event_at<((to_date+1)::timestamp at time zone private.amazon_analytics_timezone())),
 item_rows as(select i.*,o.fx,c.cost,c.missing,c.mapping_count from eligible o join public.shopify_analytics_items i on i.integration_account_id=o.integration_account_id and i.order_id=o.order_id and i.owner_id=v left join lateral private.shopify_cost(v,i.integration_account_id,i.seller_sku,o.d) c on true),
 sales as(select integration_account_id,seller_sku,max(variant_id) variant_id,max(name) name,max(image_url) image_url,count(distinct order_id) orders,sum(quantity) units,sum(gross_sales*fx) gross,sum(net_sales*fx) net,sum(quantity*cost) cost,count(*) filter(where missing>0 or mapping_count=0 or fx is null) missing from item_rows group by integration_account_id,seller_sku),
 refunds as(select r.integration_account_id,r.seller_sku,sum(r.net_amount*private.amazon_rate_to_eur(r.currency,(r.event_at at time zone private.amazon_analytics_timezone())::date)) net,count(*) filter(where private.amazon_rate_to_eur(r.currency,(r.event_at at time zone private.amazon_analytics_timezone())::date) is null) missing from public.shopify_analytics_refund_items r join stores s on s.id=r.integration_account_id where r.owner_id=v and exists(select 1 from public.shopify_analytics_orders ro where ro.integration_account_id=r.integration_account_id and ro.order_id=r.order_id and ro.owner_id=v and not ro.test) and r.event_at>=(from_date::timestamp at time zone private.amazon_analytics_timezone()) and r.event_at<((to_date+1)::timestamp at time zone private.amazon_analytics_timezone()) group by r.integration_account_id,r.seller_sku),
 catalog as(select c.integration_account_id,c.seller_sku,max(c.variant_id) variant_id,max(c.name) name,max(c.image_url) image_url,sum(c.inventory_quantity)::integer inventory from public.shopify_analytics_catalog c join stores s on s.id=c.integration_account_id where c.owner_id=v group by c.integration_account_id,c.seller_sku),
 keys as(select integration_account_id,seller_sku from sales union select integration_account_id,seller_sku from catalog union select integration_account_id,seller_sku from refunds),
 mappings as(select m.integration_account_id,m.seller_sku,(array_agg(p.id order by p.name))[1] product_id,string_agg(p.name,' + ' order by p.name) name,(array_agg(m.consumption_factor order by p.name))[1] factor from public.shopify_product_mappings m join public.products p on p.id=m.product_id and p.owner_id=v where m.owner_id=v group by m.integration_account_id,m.seller_sku),
 rows as(select k.*,st.display_name,coalesce(c.variant_id,s.variant_id) variant_id,coalesce(c.name,s.name,k.seller_sku) name,coalesce(c.image_url,s.image_url) image_url,coalesce(s.orders,0) orders,coalesce(s.units,0) units,coalesce(s.gross,0) gross,coalesce(s.net,0) net,coalesce(r.net,0) refunds,coalesce(s.cost,0) cost,coalesce(s.missing,0)+coalesce(r.missing,0) missing,c.inventory,m.product_id,m.name mapping_name,coalesce(m.factor,1) factor from keys k join stores st on st.id=k.integration_account_id left join sales s using(integration_account_id,seller_sku) left join catalog c using(integration_account_id,seller_sku) left join refunds r using(integration_account_id,seller_sku) left join mappings m using(integration_account_id,seller_sku)
 where coalesce(search,'')='' or k.seller_sku ilike '%'||search||'%' or coalesce(c.name,s.name,'') ilike '%'||search||'%'),
 sortable as(select rows.*,case v_sort when 'product_name' then name when 'mapping_product_name' then mapping_name end sort_text,case v_sort when 'units' then units when 'orders' then orders when 'gross_sales' then gross when 'net_sales' then net when 'refunds' then refunds when 'product_cost' then case when missing=0 then cost end when 'inventory_quantity' then inventory else null end sort_number from rows),
 selected as(select * from sortable order by case when v_dir='asc' then sort_text end asc nulls last,case when v_dir='desc' then sort_text end desc nulls last,case when v_dir='asc' then sort_number end asc nulls last,case when v_dir='desc' then sort_number end desc nulls last,seller_sku,integration_account_id limit v_size offset (v_page-1)*v_size)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',integration_account_id::text||':'||seller_sku,'storeId',integration_account_id,'storeName',display_name,'sku',seller_sku,'variantId',variant_id,'name',name,'imageUrl',image_url,'mappingProductId',product_id,'mappingProductName',mapping_name,'consumptionFactor',factor,'orders',orders,'units',units,'grossSales',round(gross,2),'netSales',round(net,2),'refunds',round(refunds,2),'productCost',case when missing=0 then round(cost,2) end,'shippingCost',null,'profitBeforeAds',null,'profitComplete',false,'currency','EUR','inventoryQuantity',inventory) order by case when v_dir='asc' then sort_text end asc nulls last,case when v_dir='desc' then sort_text end desc nulls last,case when v_dir='asc' then sort_number end asc nulls last,case when v_dir='desc' then sort_number end desc nulls last,seller_sku,integration_account_id) from selected),'[]'::jsonb),'total',(select count(*) from rows),'page',v_page,'pageSize',v_size) into result;
 return result;end;$$;
revoke all on function public.shopify_analytics_products(date,date,uuid[],text,integer,integer,text,text) from public,anon;grant execute on function public.shopify_analytics_products(date,date,uuid[],text,integer,integer,text,text) to authenticated;

create or replace function public.shopify_create_product_and_mapping(integration_account_id uuid,seller_sku text,product_name text,internal_sku text,base_unit text default 'ud',unit_cost numeric default null,cost_from date default null,consumption_factor numeric default 1) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v uuid:=private.shopify_analytics_owner();p uuid;today date:=(now() at time zone private.amazon_analytics_timezone())::date;begin
 if not private.app_has_permission('products') then raise exception 'Necesitas permiso de Productos para crear un producto.' using errcode='42501';end if;
 if coalesce(trim(product_name),'')='' or coalesce(trim(internal_sku),'')='' then raise exception 'Indica el nombre y el SKU del producto.';end if;
 if unit_cost is not null and (unit_cost<0 or unit_cost::text in ('NaN','Infinity','-Infinity') or coalesce(cost_from,today)>today) then raise exception 'El coste y la fecha no son válidos.';end if;
 if exists(select 1 from public.products pr where pr.owner_id=v and pr.sku=trim(internal_sku)) then raise exception 'Ya existe un producto con ese SKU.' using errcode='23505';end if;
 insert into public.products(owner_id,name,sku,base_unit,last_cost,cost_unit) values(v,trim(product_name),trim(internal_sku),coalesce(nullif(trim(base_unit),''),'ud'),unit_cost,case when unit_cost is not null then coalesce(nullif(trim(base_unit),''),'ud') end) returning id into p;
 if unit_cost is not null then insert into public.product_price_history(owner_id,product_id,price_date,purchase_unit_price,normalized_unit_price,base_unit,currency) values(v,p,coalesce(cost_from,today),unit_cost,unit_cost,coalesce(nullif(trim(base_unit),''),'ud'),'EUR');end if;
 perform public.shopify_add_product_mapping(integration_account_id,seller_sku,p,consumption_factor);return jsonb_build_object('ok',true,'created',true,'productId',p);end;$$;
alter table public.shopify_analytics_sync_state add column orders_cursor text,add column history_complete boolean not null default false;
create function private.shopify_product_owned(product uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.products p where p.id=product and p.owner_id=private.shopify_analytics_owner());$$;
revoke all on function private.shopify_product_owned(uuid) from public,anon;grant execute on function private.shopify_product_owned(uuid) to authenticated;
alter policy shopify_mapping_insert on public.shopify_product_mappings with check(owner_id=(select private.app_workspace_owner_id()) and (select private.app_has_permission('shopify')) and private.shopify_product_owned(product_id) and exists(select 1 from public.integration_accounts a where a.id=integration_account_id and a.owner_id=shopify_product_mappings.owner_id and a.provider='shopify'));
